#!/usr/bin/env python3
"""DPC audit of whether oriented endpoint data determine a vertex correction."""
import json
from pathlib import Path
P=Path(__file__).resolve();ROOT=P.parents[3];R=ROOT/'research'/'benincasa'/'results';x=json.loads((R/'cosmology_oriented_gysin_face_vertex_incidence.json').read_text());imgs=[w['image'] for w in x['underdetermination_witnesses']];assert [0,0,0] in imgs and x['required_vertex_correction'] in imgs;assert not x['correction_determined'] and not x['total_square_test_defined'];out={'schema':'marici.benincasa.cosmology-oriented-gysin-dpc.v1','problem':'Do opposite endpoint orientations and the common principal trace determine the ordered vertex correction?','bold_conjecture':'The tensor (D2-D3) tensor (0,-1/2,0,3/2) canonically maps to (0,-2,2) and closes the total differential.','named_rivals':['the zero vertex map is equally compatible','a chosen linear map gives the desired correction','a source-derived chain map fixes the ambiguity'],'risky_consequences':['every compatible face-to-vertex map must have image (0,-2,2)','the next differential must be defined and satisfy C B=0'],'strongest_falsification_attempt':{'same_input_tensor':x['gysin_data']['determined_tensor'],'compatible_images':imgs,'correction_unique':x['correction_determined'],'total_square_defined':x['total_square_test_defined']},'disposition':{'status':'falsified','surviving_scope':'endpoint data determine only the oriented Gysin tensor, not a vertex image','missing_object':x['first_missing_typed_object']},'passed':True};(R/'cosmology_oriented_gysin_dpc.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2))
